CREATE OR REPLACE FUNCTION public.purchase_apply_policy(_line uuid,_entries jsonb,_summary jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF coalesce(auth.role(),'')<>'service_role' THEN RAISE EXCEPTION 'Unauthorized'; END IF; PERFORM 1 FROM public.purchase_cc_lines WHERE id=_line FOR UPDATE; UPDATE public.purchase_cc_lines SET excluded_amount=(_summary->>'excluded')::numeric,pending_amount=(_summary->>'pending')::numeric,launched_amount=(_summary->>'launched')::numeric,effective_cc=_summary->>'effective_cc',item_states=_summary->'states' WHERE id=_line; RETURN public.purchase_replace_entries(_line,_entries,_summary->>'status',_summary->>'reason'); END $$;
REVOKE ALL ON FUNCTION public.purchase_apply_policy(uuid,jsonb,jsonb) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.purchase_apply_policy(uuid,jsonb,jsonb) TO service_role;